(x, y, t) => {
  const cx = 240, cy = 120;
  const masses = [
    [160+Math.sin(t*0.5)*120, 80+Math.cos(t*0.35)*60, 40],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.65)*70, 35],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.45+1)*100, 50],
    [100+Math.cos(t*0.7+1)*90, 200+Math.sin(t*0.55+3)*70, 25],
    [380+Math.sin(t*0.4+4)*80, 50+Math.cos(t*0.8+2)*60, 30],
    [240+Math.cos(t*0.3+5)*130, 210+Math.sin(t*0.5)*90, 45],
    [60+Math.sin(t*0.6+3)*50, 120+Math.cos(t*0.4+1)*80, 20],
    [420+Math.cos(t*0.55+2)*60, 180+Math.sin(t*0.75+4)*50, 28]
  ];
  let gx = 0, gy = 0, totalPot = 0;
  for (const [mX, mY, mass] of masses) {
    const dx = mX - x, dy = mY - y;
    const distSq = dx*dx + dy*dy + 100;
    const dist = Math.sqrt(distSq);
    const force = mass / distSq;
    gx += dx / dist * force * 800;
    gy += dy / dist * force * 800;
    totalPot += mass / dist;
  }
  const flow = Math.sin(x*0.018+t*0.25)*12+Math.cos(y*0.015-t*0.2)*10;
  const flowY = Math.cos(y*0.018-t*0.22)*12+Math.sin(x*0.016+t*0.3)*10;
  const sx = x+gx+flow, sy = y+gy+flowY;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.1,2.2],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.12,1.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.07,2.6],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.14,1.6],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.08,2.9],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.11,2.1],
    [80+Math.sin(t*0.65+2)*70,140+Math.cos(t*0.5+3)*55,0.13,1.4],
    [400+Math.cos(t*0.48+1)*65,100+Math.sin(t*0.72+4)*60,0.09,2.4]
  ];
  let aS=0,iS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.5);
  }
  const act=aS/8,inh=iS/8;
  const bg=(Math.sin(sx*0.045+sy*0.028+t*0.9)+Math.sin(sx*0.035-sy*0.045+t*1.2))/2+Math.sin((sx+sy)*0.14+t*2.8)*0.25+Math.sin((sx-sy)*0.11-t*2.2)*0.25;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.055-ang*4-t*1.8)+Math.sin(dist*0.045+ang*5-t*1.4))*0.4;
  const kinetic=Math.sqrt(gx*gx+gy*gy)*0.02;
  const energyBlend=Math.sin(kinetic*2+totalPot*0.08-t*0.5)*0.3;
  const cell=Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18)+Math.sin((sx+sy)*0.12+t)*0.5+Math.sin(sx*0.22-sy*0.08+t*0.7)*0.3)*1.8)*0.35;
  const fineDetail=Math.sin(sx*0.35+t*3)*Math.sin(sy*0.3-t*2.5)*0.15;
  const reaction=Math.tanh((act-inh*0.65+bg*0.35+spiral+energyBlend+fineDetail)*2.5);
  const blend=reaction*0.65+cell*0.35,v=blend*0.5+0.5;
  const pal=[[2,2,12],[5,15,45],[0,60,80],[0,200,220],[50,255,150],[255,255,80],[255,80,120],[200,30,80],[120,10,60],[30,5,40],[2,2,12]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.55+Math.pow(Math.abs(reaction),0.7)*0.9;
  const edgeGlow=Math.pow(Math.abs(reaction),3)*1.8;
  const edgeFactor=Math.abs(reaction)>0.6?1.0+edgeGlow*0.5:1.0;
  const bloom=Math.max(0,v-0.55)*3;
  const r=(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeFactor+bloom*80;
  const g=(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeFactor+bloom*140;
  const b=(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgeFactor+bloom*110;
  return[Math.min(255,r)|0,Math.min(255,g)|0,Math.min(255,b)|0];
}
